/// The gallery's example of `Histogram`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_zones = args.number("zones") as u32;
        let arg_height = args.number("height") as f32;
        let arg_clip_share = args.number("clip_share") as f32;
        let arg_label = args.text("label");
        let arg_scale = match args.choice("scale") {
            "Logarithmic" => HistogramScale::Logarithmic,
            _ => HistogramScale::Linear,
        };

        let hill = |center: f32| -> Vec<f32> {
            (0..256).map(|i| 400.0 * (-((i as f32 - center) / 40.0).powi(2)).exp() + 10.0).collect()
        };
        {
            let mut it = Histogram::new([
                HistogramChannel::new("Red", Color::rgb(0.9, 0.15, 0.15), hill(90.0)),
                HistogramChannel::new("Green", Color::rgb(0.15, 0.8, 0.2), hill(128.0)),
                HistogramChannel::new("Blue", Color::rgb(0.2, 0.3, 0.95), hill(170.0)),
            ]);
            it = it.zones(arg_zones);
            it = it.height(arg_height);
            it = it.clip_share(arg_clip_share);
            if !arg_label.is_empty() {
                it = it.label(arg_label.clone());
            }
            it = it.scale(arg_scale.clone());
            it
        }
    })
}

impl ComponentBook for Histogram {
    fn book() -> Meta {
        Meta::new("Media/Histogram", render)
            .summary("Overlapping channels from ready-made bins, linear or logarithmic, with clip marks.")
            .arg(ArgType::number("zones", 5.0, 0.0, 20.0, 1.0))
            .arg(ArgType::number("height", 110.0, 0.0, 440.0, 1.0))
            .arg(ArgType::number("clip_share", 0.001, 0.0, 1.0, 0.01))
            .arg(ArgType::text("label", "").description("Empty leaves it as the component has it."))
            .arg(ArgType::choice("scale", &["Linear", "Logarithmic"], "Linear"))
            .story("Example", Args::new())
            .story("Scale: Logarithmic", Args::new().with("scale", ArgValue::choice("Logarithmic")))
    }
}
